/**
 * Checkbox Component Generator
 *
 * Generates a Checkbox ComponentSet in Figma with properties:
 * - variant: default, error
 * - checked: true, false
 * - indeterminate: true, false
 * - disabled: true, false
 *
 * Reads variant definitions from component-registry.json (the source of truth).
 *
 * @see packages/kumo/src/components/checkbox/checkbox.tsx
 */

import {
  bindFillToVariable,
  bindStrokeToVariable,
  getVariableByName,
  createModeSection,
  BORDER_RADIUS,
} from "./shared";

// Import variant data from the registry (generated by build:ai-metadata)
import registry from "../../../../ai/component-registry.json";

// Extract props from registry
const checkboxProps = registry.components.Checkbox.props;

const variantProp = checkboxProps.variant as {
  values: string[];
  classes: Record<string, string>;
  descriptions: Record<string, string>;
  default: string;
};

/**
 * Checkbox dimensions from checkbox.tsx (h-4 w-4 = 16px)
 */
const CHECKBOX_SIZE = 16;

/**
 * Icon sizes for check/minus icons (size="12" in source)
 */
const ICON_SIZE = 12;

/**
 * Section padding for component display
 */
const SECTION_PADDING = 48;

/**
 * Gap between sections on the page
 */
const SECTION_GAP = 160;

/**
 * Create a check icon shape (simplified checkmark)
 */
function createCheckIcon(size: number): VectorNode {
  const vector = figma.createVector();
  vector.name = "CheckIcon";

  // Create a simple checkmark path
  // Scaled to fit within the icon size
  const scale = size / 12;
  vector.vectorPaths = [
    {
      windingRule: "NONZERO",
      // Checkmark path: starts bottom-left of check, goes to bottom point, then up-right
      data: `M ${2 * scale} ${6 * scale} L ${5 * scale} ${9 * scale} L ${10 * scale} ${3 * scale}`,
    },
  ];

  vector.strokes = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }];
  vector.strokeWeight = 2;
  vector.strokeCap = "ROUND";
  vector.strokeJoin = "ROUND";
  vector.fills = [];
  vector.resize(size, size);

  return vector;
}

/**
 * Create a minus icon shape (for indeterminate state)
 */
function createMinusIcon(size: number): VectorNode {
  const vector = figma.createVector();
  vector.name = "MinusIcon";

  // Create a horizontal line centered in the icon
  const scale = size / 12;
  const y = 6 * scale;
  vector.vectorPaths = [
    {
      windingRule: "NONZERO",
      data: `M ${2 * scale} ${y} L ${10 * scale} ${y}`,
    },
  ];

  vector.strokes = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }];
  vector.strokeWeight = 2;
  vector.strokeCap = "ROUND";
  vector.fills = [];
  vector.resize(size, size);

  return vector;
}

/**
 * Create a single checkbox component
 */
function createCheckboxComponent(
  variant: string,
  checked: boolean,
  indeterminate: boolean,
  disabled: boolean,
): ComponentNode {
  const component = figma.createComponent();
  component.name = `variant=${variant}, checked=${checked}, indeterminate=${indeterminate}, disabled=${disabled}`;

  const variantDesc = variantProp.descriptions[variant] || "";
  component.description = variantDesc;

  // Configure as a fixed-size component
  component.layoutMode = "HORIZONTAL";
  component.primaryAxisAlignItems = "CENTER";
  component.counterAxisAlignItems = "CENTER";
  component.primaryAxisSizingMode = "FIXED";
  component.counterAxisSizingMode = "FIXED";
  component.resize(CHECKBOX_SIZE, CHECKBOX_SIZE);

  // Border radius: rounded-sm = 2px
  component.cornerRadius = BORDER_RADIUS.sm;

  // Background fill
  // - Unchecked: bg-surface
  // - Checked/Indeterminate: bg-surface-inverse
  const isActive = checked || indeterminate;
  const bgVariable = isActive ? "surface-inverse" : "surface";
  const bgVar = getVariableByName(bgVariable);
  if (bgVar) {
    bindFillToVariable(component, bgVar.id);
  }

  // Ring/border styling
  // - Default variant: ring-border (hover/focus would be ring-active, but static in Figma)
  // - Error variant: ring-error
  const ringVariable = variant === "error" ? "error" : "border";
  const ringVar = getVariableByName(ringVariable);
  if (ringVar) {
    bindStrokeToVariable(component, ringVar.id, 1);
  }

  // Apply disabled state: opacity-50
  if (disabled) {
    component.opacity = 0.5;
  }

  // Add icon for checked or indeterminate state
  if (indeterminate) {
    const minusIcon = createMinusIcon(ICON_SIZE);
    // Bind icon color to text-surface-inverse
    const iconColorVar = getVariableByName("text-color-surface-inverse");
    if (iconColorVar) {
      let stroke: SolidPaint = {
        type: "SOLID",
        color: { r: 1, g: 1, b: 1 },
      };
      stroke = figma.variables.setBoundVariableForPaint(
        stroke,
        "color",
        figma.variables.getVariableById(iconColorVar.id)!,
      );
      minusIcon.strokes = [stroke];
    }
    // @ts-expect-error - VectorNode is valid child for ComponentNode
    component.appendChild(minusIcon);
    // Center the icon
    minusIcon.x = (CHECKBOX_SIZE - ICON_SIZE) / 2;
    minusIcon.y = (CHECKBOX_SIZE - ICON_SIZE) / 2;
  } else if (checked) {
    const checkIcon = createCheckIcon(ICON_SIZE);
    // Bind icon color to text-surface-inverse
    const iconColorVar = getVariableByName("text-color-surface-inverse");
    if (iconColorVar) {
      let stroke: SolidPaint = {
        type: "SOLID",
        color: { r: 1, g: 1, b: 1 },
      };
      stroke = figma.variables.setBoundVariableForPaint(
        stroke,
        "color",
        figma.variables.getVariableById(iconColorVar.id)!,
      );
      checkIcon.strokes = [stroke];
    }
    // @ts-expect-error - VectorNode is valid child for ComponentNode
    component.appendChild(checkIcon);
    // Center the icon
    checkIcon.x = (CHECKBOX_SIZE - ICON_SIZE) / 2;
    checkIcon.y = (CHECKBOX_SIZE - ICON_SIZE) / 2;
  }

  return component;
}

/**
 * Determine which combinations to generate.
 *
 * We generate a reduced set that covers meaningful states:
 * - All variants × checked states (not indeterminate, not disabled) = 2 × 2 = 4
 * - Indeterminate state: default variant only = 1
 * - Disabled states: default variant, unchecked/checked/indeterminate = 3
 * - Error + disabled: 1 (unchecked)
 *
 * Total: ~9 components (instead of 2 × 2 × 2 × 2 = 16)
 */
function shouldGenerateVariant(
  variant: string,
  checked: boolean,
  indeterminate: boolean,
  disabled: boolean,
): boolean {
  // Base states: all variants × checked (not indeterminate, not disabled)
  if (!indeterminate && !disabled) {
    return true;
  }

  // Indeterminate: only default variant, not disabled
  if (indeterminate && !disabled && variant === "default") {
    return true;
  }

  // Disabled states: default variant only
  if (disabled && variant === "default") {
    return true;
  }

  // Error + disabled: just unchecked
  if (disabled && variant === "error" && !checked && !indeterminate) {
    return true;
  }

  return false;
}

/**
 * Generate Checkbox ComponentSet
 *
 * @param page - Target page for components
 * @param startY - Y position to start placing sections
 * @returns The Y position after all sections
 */
export async function generateCheckboxComponents(
  page: PageNode,
  startY: number = 100,
): Promise<number> {
  figma.currentPage = page;

  const variants = variantProp.values;
  const checkedOptions = [false, true];
  const indeterminateOptions = [false, true];
  const disabledOptions = [false, true];

  // Generate selected combinations only
  const components: ComponentNode[] = [];

  // Layout grid spacing
  const componentGap = 16;
  const rowGap = 40;

  // Track layout by row
  let currentRow = 0;
  let currentX = 0;
  let maxRowWidth = 0;

  // Group by: variant, then states
  for (const variant of variants) {
    currentX = 0;

    for (const disabled of disabledOptions) {
      for (const indeterminate of indeterminateOptions) {
        for (const checked of checkedOptions) {
          // Skip indeterminate + checked (mutually exclusive in practice)
          if (indeterminate && checked) continue;

          if (
            !shouldGenerateVariant(variant, checked, indeterminate, disabled)
          ) {
            continue;
          }

          const component = createCheckboxComponent(
            variant,
            checked,
            indeterminate,
            disabled,
          );

          component.x = currentX;
          component.y = currentRow * rowGap;
          currentX += component.width + componentGap;
          maxRowWidth = Math.max(maxRowWidth, currentX);

          components.push(component);
        }
      }
    }

    currentRow++;
  }

  // Combine into ComponentSet
  // @ts-ignore - combineAsVariants works at runtime
  const componentSet = figma.combineAsVariants(components, page);
  componentSet.name = "Checkbox";
  componentSet.description =
    "Checkbox component with variant, checked, indeterminate, and disabled properties";

  componentSet.layoutMode = "NONE";

  // Calculate content dimensions
  const contentWidth = componentSet.width;
  const contentHeight = componentSet.height;

  // Create light mode section
  const lightSection = createModeSection(page, "Checkbox", "light");
  lightSection.frame.resize(
    contentWidth + SECTION_PADDING * 2,
    contentHeight + SECTION_PADDING * 2,
  );

  // Create dark mode section
  const darkSection = createModeSection(page, "Checkbox", "dark");
  darkSection.frame.resize(
    contentWidth + SECTION_PADDING * 2,
    contentHeight + SECTION_PADDING * 2,
  );

  // Move ComponentSet into light section frame
  lightSection.frame.appendChild(componentSet);
  componentSet.x = SECTION_PADDING;
  componentSet.y = SECTION_PADDING;

  // Create instances for dark section
  for (const component of components) {
    const instance = component.createInstance();
    instance.x = component.x + SECTION_PADDING;
    instance.y = component.y + SECTION_PADDING;
    darkSection.frame.appendChild(instance);
  }

  // Resize sections to fit content with padding
  const totalWidth = contentWidth + SECTION_PADDING * 2;
  const totalHeight = contentHeight + SECTION_PADDING * 2;

  lightSection.section.resizeWithoutConstraints(totalWidth, totalHeight);
  darkSection.section.resizeWithoutConstraints(totalWidth, totalHeight);

  // Position sections side by side
  lightSection.section.x = 100;
  lightSection.section.y = startY;

  darkSection.section.x = 100 + totalWidth + 50;
  darkSection.section.y = startY;

  console.log(
    `✅ Generated Checkbox ComponentSet with ${components.length} variants (light + dark)`,
  );

  return startY + totalHeight + SECTION_GAP;
}

/**
 * Exports for tests
 */
export const CHECKBOX_VARIANTS_EXPORT = variantProp.values;
